(() => {
 const host=document.getElementById('dataHub');if(!host)return;
 const request=window.aedAdminRequest,esc=escapeText;
 let sources=[],source=null,upload=null,batches=[],activeBatch=null,selected=new Set(),page=0,busy=false;
 const pageSize=100;
 const labels={source_updated_at:'Data zmiany źródła (ISO 8601)',defibrillator_id:'ID w źródle',lat:'Szerokość geograficzna',lon:'Długość geograficzna',location_object_name:'Nazwa miejsca',location_city:'Miejscowość',location_street:'Ulica',location_building:'Numer budynku',location_postcode:'Kod pocztowy',location_description:'Jak znaleźć AED',device_access_description:'Godziny dostępu',device_availability:'Dostępność',device_public_access:'Warunki dostępu',device_location:'Wewnątrz / na zewnątrz',device_manufacturer:'Producent',device_specifications:'Specyfikacja źródła',address:'Pełny adres',device_operational_status:'Stan urządzenia'};
 host.innerHTML=`<section class="data-card"><div class="data-card-heading"><div><h2>Rejestr źródeł</h2><p>Każde źródło ma wydawcę, zakres terytorialny i trwałe identyfikatory AED. Wydawca źródła nie jest automatycznie odpowiedzialnym dostawcą zbioru wynikowego.</p></div><button type="button" id="newSource" class="hub-secondary">Dodaj źródło</button></div><label class="hub-label">Źródło danych<select id="hubSource"></select></label><p id="sourceStatus" class="data-caption" role="status"></p><details id="sourceSettings"><summary>Ustawienia źródła</summary><form id="sourceForm" class="hub-form"><label>Nazwa źródła<input name="title" maxlength="200" required></label><label>Wydawca źródła<input name="publisher" maxlength="200" required></label><label>Kod TERC gminy (puste: cała Polska)<input name="terc" pattern="[0-9]{7}" maxlength="7" placeholder="Np. 1465011"></label><label>Nazwa obszaru<input name="areaName" maxlength="120"></label><label>Sposób aktualizacji<select name="mode"><option value="file">Plik przesyłany przez administratora</option><option value="api">Publiczny URL / API</option></select></label><label>Format<select name="format"><option value="json">JSON (Warszawa)</option><option value="geojson">GeoJSON</option><option value="csv">CSV</option><option value="xlsx">XLSX</option></select></label><label class="hub-wide">URL źródła<input name="url" type="url" placeholder="https://…"></label><label>Licencja / warunki wykorzystania<input name="licenseName" maxlength="200" required placeholder="Np. CC BY 4.0"></label><label>Adres warunków<input name="licenseUrl" type="url"></label><label class="hub-checkbox hub-wide"><input name="licenseConfirmed" type="checkbox">Potwierdzam warunki ponownego wykorzystania danych z tego źródła</label><label class="hub-checkbox hub-wide"><input name="daily" type="checkbox">Automatycznie sprawdzaj źródło co 24 godziny (dla URL / API)</label><div class="hub-wide hub-actions"><button type="submit" class="admin-primary">Zapisz źródło</button><button type="button" id="syncSource" class="hub-secondary">Pobierz teraz</button></div></form></details><p id="hubMessage" role="status" aria-live="polite"></p></section>
 <section class="data-card"><div class="data-card-heading"><div><h2>Import i porównanie wersji</h2><p>JSON, GeoJSON, CSV lub XLSX · do 15 MB · do 25 000 rekordów</p></div><div class="data-downloads"><a href="/api/templates/warsaw.json">Przykład JSON</a><a href="/api/templates/aed.csv">Szablon CSV</a><a href="/api/templates/aed.xlsx">Szablon XLSX</a></div></div><p>Ponowny import aktualizuje rekordy po ID. Opublikowane dane zmieniają się po decyzji administratora.</p><form id="hubUploadForm" class="data-import-form"><label>Plik z bazą AED<input type="file" id="hubFile" accept=".json,.geojson,.csv,.xlsx" required></label><button type="submit" class="admin-primary">Wczytaj plik</button></form><div id="hubMapping" hidden></div><p id="uploadStatus" role="status" aria-live="polite"></p></section>
 <section class="data-card"><div class="data-card-heading"><div><h2>Importy do rozpatrzenia</h2><p>Brak rekordu w pliku wymaga osobnej decyzji o jego usunięciu z opublikowanej bazy.</p></div><button type="button" id="refreshImports" class="hub-secondary">Odśwież</button></div><label class="hub-label">Wybierz import<select id="hubBatch"></select></label><div id="batchDetails"></div><p id="batchMessage" role="status" aria-live="polite"></p><div id="publicationHistory"></div></section>`;
 const message=host.querySelector('#hubMessage'),sourceSelect=host.querySelector('#hubSource'),form=host.querySelector('#sourceForm'),mappingHost=host.querySelector('#hubMapping'),uploadMessage=host.querySelector('#uploadStatus'),batchSelect=host.querySelector('#hubBatch'),details=host.querySelector('#batchDetails'),batchMessage=host.querySelector('#batchMessage');
 const publication=document.createElement('section');publication.className='data-card';publication.innerHTML=`<h2>Odpowiedzialność i dane.gov.pl</h2><p id="responsibleProvider" class="data-caption" role="status">Odpowiedzialny dostawca zbioru: nie wyznaczono.</p><p class="data-caption">Źródła danych i decyzje administratora są opisane osobno. Publikacja w dane.gov.pl wymaga organizacji, która przyjmie odpowiedzialność za zbiór, oraz jej profilu w portalu.</p><form id="portalForm" class="hub-form"><label>Publiczny adres aplikacji (HTTPS)<input name="publicBaseUrl" type="url" placeholder="https://twoja-domena.pl"></label><label>Odpowiedzialna organizacja<input name="publisher" maxlength="200" placeholder="Nie wyznaczono"></label><label>Identyfikator profilu dostawcy w dane.gov.pl<input name="providerIdentifier" maxlength="100"></label><label class="hub-checkbox hub-wide"><input name="responsibilityAccepted" type="checkbox">Wskazana organizacja przyjęła odpowiedzialność za zbiór (deklaracja administratora)</label><div class="hub-actions hub-wide"><button type="submit" class="admin-primary">Zapisz ustawienia publikacji</button><a class="hub-secondary" href="/api/admin/publication/preview">Pobierz roboczy podgląd XML</a><a class="hub-secondary" id="portalXml" href="/api/dane-gov.xml" hidden>XML dla portalu</a><a class="hub-secondary" id="portalMd5" href="/api/dane-gov.xml.md5" hidden>Suma MD5</a></div></form><p id="portalMessage" role="status">Odpowiedzialny dostawca zbioru: nie wyznaczono. Dostępny jest roboczy podgląd XML.</p>`;host.appendChild(publication);
 const portalForm=publication.querySelector('form'),portalMessage=publication.querySelector('#portalMessage');
 function showPublication(result){
  publication.querySelector('#responsibleProvider').textContent='Odpowiedzialny dostawca zbioru: '+result.responsibility.label+(result.responsibility.status==='declared'?' (deklaracja administratora).':'.');
  publication.querySelector('#portalXml').hidden=!result.export_ready;publication.querySelector('#portalMd5').hidden=!result.export_ready;
  portalMessage.textContent=result.export_ready?'Eksport XML jest przygotowany. Źródło wymaga osobnej rejestracji w profilu dostawcy dane.gov.pl. Połączenie z portalem nie zostało potwierdzone.':result.missing.join(' ')+' Dostępny jest roboczy podgląd XML. Połączenie z portalem nie zostało skonfigurowane.';
 }
 request('/api/admin/publication').then(result=>{for(const name of ['publicBaseUrl','publisher','providerIdentifier'])portalForm.elements[name].value=result.settings[name]||'';portalForm.elements.responsibilityAccepted.checked=result.settings.responsibilityAccepted===true;showPublication(result);}).catch(error=>portalMessage.textContent=error.message);
 portalForm.onsubmit=async event=>{event.preventDefault();const button=portalForm.querySelector('button');button.disabled=true;try{const input=Object.fromEntries(new FormData(portalForm));input.responsibilityAccepted=portalForm.elements.responsibilityAccepted.checked;const result=await request('/api/admin/publication',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});showPublication(result);}catch(error){portalMessage.textContent=error.message;}finally{button.disabled=false;}};
 const date=value=>value?new Date(value).toLocaleString('pl-PL'):'—';
 function setBusy(value){busy=value;sourceSelect.disabled=value;host.querySelectorAll('button').forEach(button=>{if(value){if(!Object.hasOwn(button.dataset,'busyDisabled'))button.dataset.busyDisabled=String(button.disabled);button.disabled=true;}else if(Object.hasOwn(button.dataset,'busyDisabled')){button.disabled=button.dataset.busyDisabled==='true';delete button.dataset.busyDisabled;}});}
 function fillSource(){
  source=sources.find(item=>item.id===sourceSelect.value)||null;form.reset();
  if(source){for(const [name,value]of Object.entries({title:source.title,publisher:source.publisher,terc:source.terc,areaName:source.area_name,mode:source.mode,format:source.format,url:source.url,licenseName:source.license?.name,licenseUrl:source.license?.url}))form.elements[name].value=value||'';form.elements.daily.checked=source.daily;form.elements.licenseConfirmed.checked=source.license?.confirmed;}
  host.querySelector('#syncSource').hidden=!source||source.mode!=='api';
  host.querySelector('#sourceStatus').textContent=source?`${source.publisher} · ${source.area_name||'Polska'} · sprawdzono: ${date(source.lastCheckedAt)} · opublikowano: ${date(source.lastPublishedAt)}${source.lastError?' · Błąd: '+source.lastError:''}${source.authorizationRequired?' · Autoryzacja po stronie serwera':''}`:'Uzupełnij dane nowego źródła.';
  upload=null;mappingHost.hidden=true;uploadMessage.textContent='';refreshBatches();
 }
 async function loadSources(selectId){const result=await request('/api/admin/sources');sources=result.sources;const city=window.aedSelectedCity,visible=sources.filter(item=>!city||!item.terc||item.terc===city);sourceSelect.innerHTML=visible.map(item=>`<option value="${esc(item.id)}">${esc(item.title)}${item.terc?' · '+esc(item.terc):''}</option>`).join('');if(selectId&&visible.some(item=>item.id===selectId))sourceSelect.value=selectId;else if(city&&visible.some(item=>item.terc===city))sourceSelect.value=visible.find(item=>item.terc===city).id;fillSource();}
 sourceSelect.onchange=fillSource;
 host.querySelector('#newSource').onclick=()=>{source=null;sourceSelect.selectedIndex=-1;form.reset();const area=window.aedGetSelectedArea?.();form.elements.terc.value=area?.id||'';form.elements.areaName.value=area?.name||'';host.querySelector('#sourceSettings').open=true;host.querySelector('#syncSource').hidden=true;host.querySelector('#sourceStatus').textContent='Nowe źródło';message.textContent='';form.elements.title.focus();};
 form.onsubmit=async event=>{
  event.preventDefault();setBusy(true);message.textContent='Zapisywanie źródła…';
  try{const input=Object.fromEntries(new FormData(form));input.licenseConfirmed=form.elements.licenseConfirmed.checked;input.daily=form.elements.daily.checked;if(source){input.id=source.id;input.version=source.version;}const result=await request('/api/admin/sources',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});await loadSources(result.source.id);message.textContent='Zapisano źródło.';host.querySelector('#sourceSettings').open=false;}
  catch(error){message.textContent=error.message;}finally{setBusy(false);}
 };
 host.querySelector('#syncSource').onclick=async()=>{if(!source)return;setBusy(true);message.textContent='Pobieranie i porównywanie danych…';try{const result=await request('/api/admin/sources/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sourceId:source.id})});message.textContent=result.unchanged?'Źródło sprawdzone. Dane bez zmian.':'Przygotowano import do zatwierdzenia.';await loadSources(source.id);}catch(error){message.textContent=error.message;}finally{setBusy(false);}};
 function fileContent(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Nie udało się odczytać pliku.'));reader.readAsDataURL(file);});}
 host.querySelector('#hubUploadForm').onsubmit=async event=>{
  event.preventDefault();const file=host.querySelector('#hubFile').files[0];if(!file||file.size>15000000){uploadMessage.textContent='Wybierz plik do 15 MB.';return;}if(!source){uploadMessage.textContent='Najpierw zapisz i wybierz źródło.';return;}setBusy(true);uploadMessage.textContent='Odczytywanie pliku…';
  try{upload=await request('/api/admin/uploads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,content:await fileContent(file)})});renderMapping();uploadMessage.textContent=`Wczytano ${upload.total} rekordów. Sprawdź przypisanie kolumn i przygotuj porównanie.`;}
  catch(error){uploadMessage.textContent=error.message;}finally{setBusy(false);}
 };
 function renderMapping(){mappingHost.hidden=false;mappingHost.innerHTML=`<h3>Przypisanie kolumn</h3><p class="data-caption">Wymagane: ID w źródle i obie współrzędne. Pierwszy arkusz XLSX jest odczytywany domyślnie.</p><div class="hub-form">${upload.fields.map(field=>`<label>${esc(labels[field]||field)}${['defibrillator_id','lat','lon'].includes(field)?' *':''}<select data-field="${field}"><option value="">Brak kolumny</option>${upload.columns.map(column=>`<option value="${esc(column)}"${upload.mapping[field]===column?' selected':''}>${esc(column)}</option>`).join('')}</select></label>`).join('')}</div><details><summary>Podgląd pierwszych rekordów</summary><pre class="hub-sample">${esc(JSON.stringify(upload.sample,null,2))}</pre></details><button type="button" id="prepareImport" class="admin-primary">Przygotuj porównanie wersji</button>`;mappingHost.querySelector('#prepareImport').onclick=prepareImport;}
 async function prepareImport(){
  if(!source||!upload)return;const mapping=Object.fromEntries([...mappingHost.querySelectorAll('[data-field]')].filter(input=>input.value).map(input=>[input.dataset.field,input.value]));setBusy(true);uploadMessage.textContent='Sprawdzanie rekordów i porównywanie wersji…';
  try{const result=await request('/api/admin/imports/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uploadId:upload.uploadId,sourceId:source.id,mapping})});if(!result.valid){uploadMessage.textContent=`Nie można zatwierdzić importu. Błędy: ${result.errors.length}. `+result.errors.slice(0,15).map(error=>`Wiersz ${error.row}: ${error.message}`).join(' · ');return;}uploadMessage.textContent=result.unchanged?'Plik jest zgodny z opublikowaną wersją. Nie utworzono duplikatów.':result.reused?(result.batch.pending?'Ten sam import już oczekuje na decyzję.':'Ten import został już rozpatrzony. Nie utworzono nowego pakietu.'):'Porównanie gotowe. Wybierz zmiany do zatwierdzenia poniżej.';await refreshBatches(result.batch?.id);}
  catch(error){uploadMessage.textContent=error.message;}finally{setBusy(false);}
 }
 async function refreshBatches(selectId){
  try{const result=await request('/api/admin/imports'+(source?'?source='+encodeURIComponent(source.id):''));batches=result.batches;const previous=selectId||activeBatch?.id;batchSelect.innerHTML=batches.length?batches.map(batch=>`<option value="${batch.id}">${esc(batch.filename)} · ${date(batch.createdAt)} · oczekujące: ${batch.pending}${batch.stale?' · wymaga ponownego porównania':''}</option>`).join(''):'<option value="">Brak importów</option>';if(previous&&batches.some(batch=>batch.id===previous))batchSelect.value=previous;chooseBatch();host.querySelector('#publicationHistory').innerHTML='<h3>Historia publikacji</h3>'+result.history.filter(item=>!source||item.sourceId===source.id).slice(0,15).map(item=>`<div class="hub-history"><span>${esc(item.action==='undo'?'Cofnięto decyzję':item.action==='reject'?'Odrzucono zmiany':'Opublikowano zmiany')} · ${date(item.at)}${item.undoneAt?' · cofnięto':''}</span>${item.action!=='undo'&&!item.undoneAt?`<button type="button" data-undo-publication="${item.id}" class="hub-secondary">Cofnij</button>`:''}</div>`).join('');}
  catch(error){batchMessage.textContent=error.message;}
 }
 function chooseBatch(){activeBatch=batches.find(batch=>batch.id===batchSelect.value)||null;selected=new Set(activeBatch?.changes.filter(change=>change.status==='pending'&&change.type!=='missing'&&!change.possibleDuplicates?.length&&!change.after?.quality_flags?.length).map(change=>change.id)||[]);page=0;renderBatch();}
 function changeDetails(change){if(!change.before)return '';const old={...change.before.properties,lat:change.before.lat,lon:change.before.lon},next=change.after?{...change.after.properties,lat:change.after.lat,lon:change.after.lon}:{};return (change.rawChanged?'<p>Zmieniono również oryginalną treść rekordu źródłowego.</p>':'')+Object.keys(old).filter(key=>JSON.stringify(old[key])!==JSON.stringify(next[key])).map(key=>`<div><strong>${esc(labels[key]||key)}</strong>: ${esc(old[key]??'—')} → ${esc(next[key]??'—')}</div>`).join('');}
 function renderBatch(){
  if(!activeBatch){details.innerHTML='<p class="data-caption">Wczytaj plik lub pobierz dane ze źródła.</p>';return;}
  const batch=activeBatch,start=page*pageSize,rows=batch.changes.slice(start,start+pageSize);
  details.innerHTML=`<div class="hub-counts"><span>Nowe: <b>${batch.counts.add}</b></span><span>Zmienione: <b>${batch.counts.change}</b></span><span>Brak w pliku: <b>${batch.counts.missing}</b></span><span>Bez zmian: <b>${batch.counts.unchanged}</b></span></div>${batch.stale?'<p class="hub-warning">Opublikowano nowsze dane. Wczytaj ponownie plik, aby przygotować aktualne porównanie.</p>':''}<div class="hub-actions"><button type="button" data-select-safe class="hub-secondary">Wybierz nowe i zmienione</button><button type="button" data-clear-selection class="hub-secondary">Wyczyść wybór</button><button type="button" data-decide="approve" class="admin-primary"${batch.stale?' disabled':''}>Zatwierdź wybrane (${selected.size})</button><button type="button" data-decide="reject" class="hub-secondary">Odrzuć wybrane</button></div><div class="data-table-scroll"><table class="data-table"><thead><tr><th>Wybór</th><th>Zmiana</th><th>AED</th><th>Szczegóły</th></tr></thead><tbody>${rows.map(change=>{const point=change.after||change.before;return `<tr><td><input type="checkbox" data-change-id="${esc(change.id)}" aria-label="Wybierz AED ${esc(change.sourceRecordId)}"${selected.has(change.id)?' checked':''}${change.status!=='pending'?' disabled':''}></td><td>${esc({add:'Nowy',change:'Zmiana',missing:'Brak w pliku'}[change.type])}<small>${esc({pending:'Oczekuje',approved:'Zatwierdzono',rejected:'Odrzucono'}[change.status])}</small></td><td><strong>${esc(point.properties.location_object_name||'AED')}</strong><small>ID: ${esc(change.sourceRecordId)} · ${esc(point.properties.location_city||'')}</small><small>${esc(point.properties.address||[point.properties.location_street,point.properties.location_building].filter(Boolean).join(' '))}</small></td><td>${change.type==='missing'?'<span class="hub-warning">Zaznaczenie i zatwierdzenie usunie rekord tego źródła z publikacji.</span>':''}${change.possibleDuplicates?.length?'<span class="hub-warning">Możliwy duplikat w pobliżu — sprawdź na mapie.</span>':''}${change.after?.quality_flags?.includes('outside_declared_scope')?'<span class="hub-warning">Współrzędne poza deklarowaną gminą źródła — sprawdź na mapie.</span>':''}${change.type==='change'?`<details><summary>Pokaż różnice</summary>${changeDetails(change)}</details>`:''}<button type="button" data-map-id="${esc(change.id)}" class="hub-secondary">Mapa</button><div class="hub-originals">${change.before?`<a href="/api/admin/import-record?batch=${batch.id}&amp;id=${encodeURIComponent(change.id)}&amp;side=before" target="_blank" rel="noopener">Oryginał przed</a>`:''}${change.after?`<a href="/api/admin/import-record?batch=${batch.id}&amp;id=${encodeURIComponent(change.id)}&amp;side=after" target="_blank" rel="noopener">Oryginał po</a>`:''}</div></td></tr>`;}).join('')}</tbody></table></div><div class="hub-actions"><button type="button" data-prev class="hub-secondary"${page===0?' disabled':''}>Poprzednie</button><span>${start+1}–${Math.min(start+pageSize,batch.changes.length)} z ${batch.changes.length}</span><button type="button" data-next class="hub-secondary"${start+pageSize>=batch.changes.length?' disabled':''}>Następne</button></div>`;
 }
 details.addEventListener('change',event=>{const checkbox=event.target.closest('[data-change-id]');if(!checkbox)return;if(checkbox.checked)selected.add(checkbox.dataset.changeId);else selected.delete(checkbox.dataset.changeId);const approve=details.querySelector('[data-decide=approve]');approve.textContent='Zatwierdź wybrane ('+selected.size+')';});
 details.addEventListener('click',async event=>{
  const button=event.target.closest('button');if(!button||busy||!activeBatch)return;
  if(button.hasAttribute('data-prev')){page--;renderBatch();return;}if(button.hasAttribute('data-next')){page++;renderBatch();return;}
  if(button.hasAttribute('data-select-safe')){selected=new Set(activeBatch.changes.filter(change=>change.status==='pending'&&change.type!=='missing'&&!change.possibleDuplicates?.length&&!change.after?.quality_flags?.length).map(change=>change.id));renderBatch();return;}
  if(button.hasAttribute('data-clear-selection')){selected.clear();renderBatch();return;}
  if(button.dataset.mapId){const change=activeBatch.changes.find(change=>change.id===button.dataset.mapId),record=change.after||change.before;window.aedShowOnMap([record]);return;}
  if(!button.dataset.decide)return;if(!selected.size){batchMessage.textContent='Wybierz co najmniej jedną zmianę.';return;}setBusy(true);batchMessage.textContent='Zapisywanie decyzji…';
  try{await request('/api/admin/imports/decisions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({batchId:activeBatch.id,version:activeBatch.version,action:button.dataset.decide,ids:[...selected]})});batchMessage.textContent=button.dataset.decide==='approve'?'Opublikowano wybrane zmiany.':'Odrzucono wybrane zmiany.';window.dispatchEvent(new CustomEvent('registry-changed',{detail:{source:'imports'}}));await refreshBatches(activeBatch.id);}
  catch(error){batchMessage.textContent=error.message;}finally{setBusy(false);renderBatch();}
 });
 host.querySelector('#publicationHistory').addEventListener('click',async event=>{const button=event.target.closest('[data-undo-publication]');if(!button||busy)return;setBusy(true);try{await request('/api/admin/imports/undo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:button.dataset.undoPublication})});batchMessage.textContent='Cofnięto decyzję. Zmiany wróciły do rozpatrzenia.';await refreshBatches();window.dispatchEvent(new CustomEvent('registry-changed',{detail:{source:'imports'}}));}catch(error){batchMessage.textContent=error.message;}finally{setBusy(false);renderBatch();}});
 batchSelect.onchange=chooseBatch;host.querySelector('#refreshImports').onclick=()=>refreshBatches();
 window.addEventListener('city-changed',()=>loadSources(source?.id).catch(error=>message.textContent=error.message));
 loadSources().catch(error=>message.textContent=error.message);
})();
